svg.script:
// --- SVG document shims (see tools/make_svg_page.py) ---
(function () {
  var XHTML = 'http://www.w3.org/1999/xhtml';

  // createElement must produce HTML-namespaced elements, or a created <script> never runs.
  var svgCreate = document.createElement.bind(document);
  document.createElement = function (tag) {
    try { return document.createElementNS(XHTML, tag); }
    catch (e) { return svgCreate(tag); }
  };

  // SVG documents have no <base>.
  //
  // The HTML page redirects every relative fetch to the CDN with
  // <base href="https://cdn.jsdelivr.net/.../">. That element is HTML-head-only, and
  // xml:base is gone from modern browsers, so in an SVG the page fetched
  // "Build/....part000" relative to wherever the SVG was served and got a 404.
  // Resolving relative URLs against the same root reproduces what <base> did.
  var BASE = 'https://cdn.jsdelivr.net/gh/dashiellbenton/ports-data@ccf4cc894bb479efcfcff214bc865d06560677ac/papersplease/';
  if (BASE) {
    var isAbsolute = function (u) { return /^[a-z][a-z0-9+.-]*:/i.test(u) || u.indexOf('//') === 0; };
    var realFetch = window.fetch && window.fetch.bind(window);
    if (realFetch) {
      window.fetch = function (input, init) {
        try {
          if (typeof input === 'string' && !isAbsolute(input)) {
            input = new URL(input, BASE).toString();
          } else if (input && typeof input === 'object' && input.url && !isAbsolute(input.url)) {
            input = new Request(new URL(input.url, BASE).toString(), input);
          }
        } catch (e) {}
        return realFetch(input, init);
      };
    }
    // A <script src="Build/..."> resolves against the DOCUMENT base, which fetch shims do
    // not touch -- the payload downloaded from the CDN but the loader script itself 404'd
    // against the page's own host. Absolutise relative script sources on assignment.
    try {
      var srcDesc = Object.getOwnPropertyDescriptor(HTMLScriptElement.prototype, 'src');
      if (srcDesc && srcDesc.set) {
        Object.defineProperty(HTMLScriptElement.prototype, 'src', {
          configurable: true,
          get: srcDesc.get,
          set: function (v) {
            try {
              if (typeof v === 'string' && !isAbsolute(v)) { v = new URL(v, BASE).toString(); }
            } catch (e) {}
            srcDesc.set.call(this, v);
          }
        });
      }
    } catch (e) {}

    // Unity's loader reaches for XMLHttpRequest in places too.
    var realOpen = XMLHttpRequest.prototype.open;
    XMLHttpRequest.prototype.open = function (method, url) {
      try {
        if (typeof url === 'string' && !isAbsolute(url)) {
          arguments[1] = new URL(url, BASE).toString();
        }
      } catch (e) {}
      return realOpen.apply(this, arguments);
    };
  }

  // document.body is null in an SVG document; point it at the real <body> inside the
  // foreignObject so the loader's appendChild/fullscreen/pointerlock calls land somewhere.
  var body = document.getElementById('svg-body');
  if (body) {
    try {
      Object.defineProperty(document, 'body', {
        configurable: true,
        get: function () { return body; }
      });
    } catch (e) {}
  }
})();


(function () {
  "use strict";
  var DATA = (window.__ppDataRoot || "data/");
  var LANGS = ["cs","de","en","es","eu","fr","id","it","ja","ko","pl","pt-BR","ru","tr","ukr","zh"];
  var PREFIX = "papersplease:";
  var assets = window.__ppAssets = window.__ppAssets || {};
  var loading = document.getElementById("pp-loading");

  // streamed assets (audio). A single-file build replaces this with its part loader.
  window.__ppFetch = window.__ppFetch || function (name) {
    return fetch(DATA + name).then(function (r) {
      if (!r.ok) throw new Error(name + ": " + r.status);
      return r.arrayBuffer();
    });
  };

  function fit() {
    var c = document.getElementById("pp-canvas");
    if (!c.width) return;
    var sx = window.innerWidth / c.width, sy = window.innerHeight / c.height;
    var s = Math.min(sx, sy);
    if (s >= 1) s = Math.floor(s * c.width) / c.width;
    c.style.width = Math.floor(c.width * s) + "px";
    c.style.height = Math.floor(c.height * s) + "px";
  }
  window.addEventListener("resize", fit);

  // ---- save export / import (G8.3) ----
  document.getElementById("pp-export").onclick = function () {
    var out = {}, skipped = [];
    for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i);
      if (k.indexOf(PREFIX) === 0) out[k.substring(PREFIX.length)] = localStorage.getItem(k);
      else skipped.push(k);
    }
    if (skipped.length) console.log("save export skipped non-game keys:", skipped);
    var blob = new Blob([JSON.stringify({ game: "papersplease-web", version: 1, saves: out }, null, 1)], { type: "application/json" });
    var a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = "papersplease-saves.json";
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(function () { URL.revokeObjectURL(a.href); }, 1000);
  };
  var fileInput = document.getElementById("pp-import-file");
  document.getElementById("pp-import").onclick = function () { fileInput.click(); };
  fileInput.onchange = function () {
    var f = fileInput.files[0];
    if (!f) return;
    f.text().then(function (txt) {
      var data = JSON.parse(txt);
      if (!data || data.game !== "papersplease-web" || typeof data.saves !== "object") throw new Error("not a Papers, Please web save file");
      if (!confirm("Replace all current saves with the ones in this file?")) return;
      var drop = [];
      for (var i = 0; i < localStorage.length; i++) { var k = localStorage.key(i); if (k.indexOf(PREFIX) === 0) drop.push(k); }
      drop.forEach(function (k) { localStorage.removeItem(k); });
      Object.keys(data.saves).forEach(function (k) { localStorage.setItem(PREFIX + k, String(data.saves[k])); });
      location.reload();
    }).catch(function (e) { alert("Could not load save: " + e.message); });
  };

  // ---- boot ----
  var files = ["assets/Art.dat"].concat(LANGS.map(function (l) { return "loc/" + l + ".zip"; }));
  var urls = { "assets/Art.dat": DATA + "Art.dat" };
  LANGS.forEach(function (l) { urls["loc/" + l + ".zip"] = DATA + "loc/" + l + ".zip"; });
  var done = 0;
  Promise.all(files.map(function (name) {
    if (assets[name]) { done++; return null; }
    return fetch(urls[name]).then(function (r) {
      if (!r.ok) throw new Error(name + ": " + r.status);
      return r.arrayBuffer();
    }).then(function (ab) {
      assets[name] = ab; done++;
      loading.textContent = "Loading… " + done + "/" + files.length;
    });
  })).then(function () {
    // browsers keep audio locked until a user gesture, and the title animation runs on the
    // music clock, so boot the game from a click (skipped when autoplay is already allowed)
    function boot() {
      var s = document.createElement("script");
      s.src = window.__ppGameJs || "game.js";
    s.onload = function () {
      loading.style.display = "none";
      fit();
      var c = document.getElementById("pp-canvas");
      new ResizeObserver(fit).observe(c);
    };
      document.body.appendChild(s);
    }
    var probe = null;
    try { probe = new (window.AudioContext || window.webkitAudioContext)(); } catch (e) {}
    var unlocked = !probe || probe.state === "running";
    if (probe) probe.close();
    if (unlocked || window.__ppNoGate) { boot(); return; }
    loading.textContent = "Click to play";
    loading.style.cursor = "pointer";
    var go = function () {
      loading.removeEventListener("pointerdown", go);
      window.removeEventListener("keydown", go);
      loading.textContent = "Loading…";
      boot();
    };
    loading.addEventListener("pointerdown", go);
    window.addEventListener("keydown", go);
  }).catch(function (e) {
    loading.textContent = "Failed to load: " + e.message;
  });
})();
